#!/usr/bin/env python3
"""Осмотр читает тот профиль, которым человек пользуется, и все области MCP.

Два сценария пришли из внешней проверки и переписаны здесь регрессионными
тестами ПРАВИЛЬНОГО поведения.

ПЕРВЫЙ — чужой профиль. Сборщик фактов брал каталог настроек как
`Path.home() / ".claude"` и на этом останавливался. Хост так не делает:
переменная `CLAUDE_CONFIG_DIR` переносит туда всё, что документация зовёт
`~/.claude`. На машине с отдельным профилем доклад описывал НЕ ТОТ каталог —
и ни строкой не говорил, какой именно он прочитал. Инструмент, который ищет
у других расхождение между утверждением и измерением, сам утверждал про
настройки, в которые не заглядывал.

ВТОРОЙ — области MCP. Учитывался один верхний `mcpServers` общего конфига.
Сервер, добавленный для ЭТОГО проекта, и сервер из `.mcp.json` команды в
список не попадали. MCP-сервер — это произвольное исполнение кода, и недосчёт
здесь не косметика: «серверов один» при трёх настроенных читается как
измерение и закрывает вопрос.

Что здесь заперто:
  · при заданном `CLAUDE_CONFIG_DIR` читается назначенный профиль, а не
    домашний, и прочитанный путь назван в фактах поимённо;
  · общий конфиг хоста берётся рядом с активным профилем, поэтому его
    MCP-серверы — это серверы ТОГО ЖЕ профиля, а не соседнего;
  · сервер области проекта — и из общего конфига, и из `.mcp.json` — доезжает
    до доклада;
  · существующая, но неразобранная область названа непрочитанной, а не
    сведена к пустоте: «не прочитал» обязано отличаться от «там пусто»;
  · у общего конфига НЕТ запасного адреса: нет файла у профиля — область не
    используется, а не подменяется файлом соседнего профиля;
  · сторож, снимающий указатель на профиль, не просто объявлен, а вызван на
    входе в набор — это проверяется отдельным прогоном;
  · обратный контроль: без переменной читается домашний каталог, как прежде.

Настоящий профиль человека здесь НЕ ЧИТАЕТСЯ ни разу. Всё, что видит проба, —
временный каталог: окружение собирается с нуля, а не наследуется, `HOME`
указывает внутрь temp, `PATH` пуст, каталог проекта задан явно. Иначе «зелёно»
описывало бы машину, а не код.

Тест самодостаточен: только стандартная библиотека и сам инструмент.
"""
from __future__ import annotations

import importlib.util
import json
import os
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]
СБОРЩИК = РЕПО / "plugins" / "superstack" / "tools" / "probe" / "collect.py"
СТОРОЖ = РЕПО / "tests" / "conftest.py"

#: Имена серверов говорят, из какой они области. Совпади они — проверка
#: перестала бы различать области, ради которых написана.
ИЗ_ПОЛЬЗОВАТЕЛЬСКОЙ = "сервер-пользователя"
ИЗ_ОБЛАСТИ_ПРОЕКТА = "сервер-этого-проекта"
ИЗ_ФАЙЛА_КОМАНДЫ = "сервер-команды"
ИЗ_ДОМАШНЕГО_ПРОФИЛЯ = "сервер-домашнего-профиля"


class Проба(unittest.TestCase):
    """Общая обвязка: временная машина и запуск сборщика на ней."""

    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.корень = Path(tmp.name)
        self.проект = self.корень / "проект"
        self.проект.mkdir(parents=True)

    # ---- фикстуры -----------------------------------------------------
    def записать(self, путь: Path, данные) -> Path:
        путь.parent.mkdir(parents=True, exist_ok=True)
        текст = данные if isinstance(данные, str) else json.dumps(
            данные, ensure_ascii=False)
        путь.write_text(текст, encoding="utf-8")
        return путь

    def сервер(self, имя: str) -> dict:
        return {"mcpServers": {имя: {"command": "npx", "args": ["-y", имя]}}}

    # ---- запуск -------------------------------------------------------
    def собрать(self, **переменные) -> dict:
        """Факты сборщика. Окружение собирается С НУЛЯ.

        Наследовать окружение человека нельзя: через него на пробу протекает
        и его настоящий профиль, и его `CLAUDE_CONFIG_DIR`, — и тогда число
        зелёных тестов становится свойством машины.
        """
        среда = {
            "HOME": str(self.корень),
            "PATH": "",
            "SUPERSTACK_PROJECT_DIR": str(self.проект),
            "CLAUDE_CODE_ENTRYPOINT": "cli",
            "SUPERSTACK_IGNORE_PAUSE": "1",
            "PYTHONUTF8": "1",
            "PYTHONIOENCODING": "utf-8",
        }
        среда.update(переменные)
        p = subprocess.run([sys.executable, str(СБОРЩИК)], env=среда,
                           capture_output=True, text=True, timeout=180)
        self.assertEqual(p.returncode, 0, p.stderr[-800:])
        return json.loads(p.stdout)

    def значение(self, факты: dict, ключ: str):
        self.assertIn(ключ, факты, f"факт {ключ} не собран")
        return факты[ключ]["value"]


class ОтдельныйПрофиль(Проба):
    """Сценарий (а): `CLAUDE_CONFIG_DIR` указывает на другой каталог."""

    def setUp(self):
        super().setUp()
        # Профиль лежит СВОИМ каталогом в стороне от домашнего: иначе его
        # общий конфиг оказался бы тем же файлом, что домашний, и проверка
        # «взят у того же профиля» ничего бы не различала.
        self.профиль = self.корень / "рабочий" / ".claude"
        # Домашний профиль существует и НЕ ПУСТ — иначе «прочитали не тот»
        # было бы неотличимо от «там нечего читать».
        self.записать(self.корень / ".claude" / "settings.json",
                      {"permissions": {"defaultMode": "default",
                                       "allow": ["Read"]}})
        self.записать(self.корень / ".claude.json",
                      self.сервер(ИЗ_ДОМАШНЕГО_ПРОФИЛЯ))
        # Назначенный профиль: другой режим прав, другое число разрешений,
        # другой MCP-сервер.
        self.записать(self.профиль / "settings.json",
                      {"permissions": {"defaultMode": "plan",
                                       "allow": ["Read", "Grep", "Glob"]}})
        self.записать(self.профиль.parent / ".claude.json",
                      self.сервер(ИЗ_ПОЛЬЗОВАТЕЛЬСКОЙ))
        self.факты = self.собрать(CLAUDE_CONFIG_DIR=str(self.профиль))

    def test_настройки_взяты_из_назначенного_профиля(self):
        self.assertEqual(self.значение(self.факты, "cc.default_mode"), "plan",
                         "прочитан домашний профиль вместо назначенного")
        self.assertEqual(self.значение(self.факты, "cc.allow_count"), 3,
                         "разрешения посчитаны в чужом профиле")

    def test_прочитанный_путь_назван(self):
        """Доклад обязан говорить, о каком профиле он."""
        self.assertEqual(self.значение(self.факты, "cc.config_dir"),
                         str(self.профиль),
                         "сборщик не назвал профиль, который прочитал")

    def test_улика_объясняет_откуда_взят_путь(self):
        улика = self.факты["cc.config_dir"]["evidence"] or ""
        self.assertIn("CLAUDE_CONFIG_DIR", улика,
                      f"неясно, почему выбран этот каталог: {улика!r}")

    def test_общий_конфиг_взят_у_того_же_профиля(self):
        объявлены = self.значение(self.факты, "mcp.declared")
        self.assertIn(ИЗ_ПОЛЬЗОВАТЕЛЬСКОЙ, объявлены, объявлены)
        self.assertNotIn(ИЗ_ДОМАШНЕГО_ПРОФИЛЯ, объявлены,
                         "MCP прочитан у соседнего профиля")


class ОбщийКонфигНеБерётсяУСоседа(Проба):
    """Запасного адреса у общего конфига нет, и это проверяется.

    Соблазн очевиден: файла по адресу профиля нет — прочитаем домашний, там
    же наверняка то же самое. Именно так доклад и уезжает в соседний профиль
    молча: имя каталога в одном факте, серверы из другого. Пусто с названной
    причиной честнее, чем полно и не о том.
    """

    def setUp(self):
        super().setUp()
        self.профиль = self.корень / "рабочий" / ".claude"
        self.записать(self.профиль / "settings.json", {})
        # У профиля своего общего конфига НЕТ, а у домашнего — есть.
        self.записать(self.корень / ".claude.json",
                      self.сервер(ИЗ_ДОМАШНЕГО_ПРОФИЛЯ))
        self.факты = self.собрать(CLAUDE_CONFIG_DIR=str(self.профиль))

    def test_сервер_соседнего_профиля_не_приписан_этому(self):
        self.assertEqual(self.значение(self.факты, "mcp.declared"), [],
                         "серверы приехали из профиля, о котором доклад не идёт")

    def test_областей_общего_конфига_просто_нет(self):
        self.assertEqual(self.значение(self.факты, "mcp.scopes_covered"), [])
        self.assertEqual(self.значение(self.факты, "mcp.scopes_unreadable"), [])


class ОбластиMCP(Проба):
    """Сценарий (б): сервер области проекта попадает в доклад."""

    def setUp(self):
        super().setUp()
        self.записать(self.корень / ".claude" / "settings.json", {})
        self.записать(self.корень / ".claude.json", {
            "mcpServers": {ИЗ_ПОЛЬЗОВАТЕЛЬСКОЙ: {"command": "npx",
                                                  "args": ["-y", "u"]}},
            "projects": {str(self.проект): {
                "mcpServers": {ИЗ_ОБЛАСТИ_ПРОЕКТА: {
                    "command": "/opt/своё/бинарь"}}}},
        })
        self.записать(self.проект / ".mcp.json", self.сервер(ИЗ_ФАЙЛА_КОМАНДЫ))
        self.факты = self.собрать()

    def test_все_три_области_в_докладе(self):
        объявлены = self.значение(self.факты, "mcp.declared")
        self.assertEqual(sorted(объявлены),
                         sorted([ИЗ_ПОЛЬЗОВАТЕЛЬСКОЙ, ИЗ_ОБЛАСТИ_ПРОЕКТА,
                                 ИЗ_ФАЙЛА_КОМАНДЫ]),
                         f"области сведены не все: {объявлены}")

    def test_про_каждую_область_сказано_что_она_прочитана(self):
        прочитаны = self.значение(self.факты, "mcp.scopes_covered")
        self.assertEqual(sorted(прочитаны), ["local", "project", "user"],
                         f"не про каждую область сказано: {прочитаны}")
        self.assertEqual(self.значение(self.факты, "mcp.scopes_unreadable"), [],
                         "непрочитанные области взялись из ниоткуда")

    def test_видно_какой_сервер_из_какой_области(self):
        по_областям = {s["scope"]: s["servers"]
                       for s in self.значение(self.факты, "mcp.by_scope")}
        self.assertEqual(по_областям.get("user"), [ИЗ_ПОЛЬЗОВАТЕЛЬСКОЙ])
        self.assertEqual(по_областям.get("local"), [ИЗ_ОБЛАСТИ_ПРОЕКТА])
        self.assertEqual(по_областям.get("project"), [ИЗ_ФАЙЛА_КОМАНДЫ])

    def test_у_каждой_области_назван_файл(self):
        """Две области живут в одном файле. Без имени файла человек не может
        перепроверить ни одну из них — а доклад продаёт именно проверяемость."""
        файлы = {s["scope"]: s["path"]
                 for s in self.значение(self.факты, "mcp.by_scope")}
        общий = str(self.корень / ".claude.json")
        self.assertEqual(файлы.get("user"), общий)
        self.assertEqual(файлы.get("local"), общий)
        self.assertEqual(файлы.get("project"), str(self.проект / ".mcp.json"))

    def test_свой_бинарь_в_области_проекта_замечен(self):
        """Признак «исполняемый файл вне менеджера пакетов» обязан работать
        во ВСЕХ областях, а не только в верхней: сервер из области проекта
        запускается ровно так же."""
        self.assertEqual(self.значение(self.факты, "mcp.local_binaries"),
                         [ИЗ_ОБЛАСТИ_ПРОЕКТА],
                         "свой бинарь в области проекта не помечен")


class НедостижимаяОбласть(Проба):
    """Сценарий (в): область есть, но не разобрана.

    Молча свести её к пустоте — это и есть тот дефект, который продукт ищет
    у других: доклад о том, чего не читали.
    """

    def setUp(self):
        super().setUp()
        self.записать(self.корень / ".claude" / "settings.json", {})
        self.записать(self.корень / ".claude.json", "{ это не JSON")
        self.записать(self.проект / ".mcp.json", self.сервер(ИЗ_ФАЙЛА_КОМАНДЫ))
        self.факты = self.собрать()

    def test_битая_область_названа_непрочитанной(self):
        непрочитанные = self.значение(self.факты, "mcp.scopes_unreadable")
        области = sorted(з["scope"] for з in непрочитанные)
        self.assertEqual(области, ["local", "user"],
                         f"битый общий конфиг не назван: {непрочитанные}")
        for з in непрочитанные:
            self.assertIn(str(self.корень / ".claude.json"), з["path"])
            self.assertTrue(з.get("reason"), "причина не названа")

    def test_битая_область_не_числится_прочитанной(self):
        прочитаны = self.значение(self.факты, "mcp.scopes_covered")
        self.assertEqual(прочитаны, ["project"],
                         f"непрочитанное записано в прочитанное: {прочитаны}")

    def test_читаемая_область_рядом_всё_равно_измерена(self):
        """Одна битая область не имеет права уносить остальные."""
        self.assertEqual(self.значение(self.факты, "mcp.declared"),
                         [ИЗ_ФАЙЛА_КОМАНДЫ])

    def test_отсутствующий_файл_это_не_поломка(self):
        """Обратная сторона того же правила: чего нет — то не «не прочитано»,
        а просто не используется. Иначе непрочитанное было бы у всех и всегда,
        и разница перестала бы что-либо значить."""
        (self.проект / ".mcp.json").unlink()
        (self.корень / ".claude.json").unlink()
        факты = self.собрать()
        self.assertEqual(self.значение(факты, "mcp.scopes_unreadable"), [])
        self.assertEqual(self.значение(факты, "mcp.declared"), [])


class БезПеременнойВсёКакПрежде(Проба):
    """Сценарий (г): обратный контроль.

    Чинили выбор профиля, а не переписывали сборщик. Без переменной он обязан
    читать домашний каталог ровно как раньше — иначе «починка» была бы просто
    другой поломкой.
    """

    def setUp(self):
        super().setUp()
        self.записать(self.корень / ".claude" / "settings.json",
                      {"permissions": {"defaultMode": "acceptEdits",
                                       "allow": ["Read", "Grep"]},
                       "statusLine": {"type": "command"}})
        self.записать(self.корень / ".claude.json",
                      self.сервер(ИЗ_ДОМАШНЕГО_ПРОФИЛЯ))
        self.факты = self.собрать()

    def test_читается_домашний_каталог(self):
        self.assertEqual(self.значение(self.факты, "cc.config_dir"),
                         str(self.корень / ".claude"))
        self.assertEqual(self.значение(self.факты, "cc.default_mode"),
                         "acceptEdits")
        self.assertEqual(self.значение(self.факты, "cc.allow_count"), 2)
        self.assertTrue(self.значение(self.факты, "cc.settings_present"))

    def test_улика_говорит_что_профиль_домашний(self):
        улика = self.факты["cc.config_dir"]["evidence"] or ""
        self.assertNotIn("CLAUDE_CONFIG_DIR", улика,
                         f"переменная не задана, а улика ссылается на неё: {улика!r}")

    def test_общий_конфиг_домашнего_профиля_прочитан(self):
        self.assertEqual(self.значение(self.факты, "mcp.declared"),
                         [ИЗ_ДОМАШНЕГО_ПРОФИЛЯ])

    def test_пустая_переменная_это_её_отсутствие(self):
        """Пустая строка в окружении — не «профиль по имени пустая строка».
        Оболочка читает её как отсутствие, и проба обязана так же."""
        факты = self.собрать(CLAUDE_CONFIG_DIR="")
        self.assertEqual(self.значение(факты, "cc.config_dir"),
                         str(self.корень / ".claude"))
        self.assertEqual(self.значение(факты, "cc.default_mode"), "acceptEdits")


class НаборНеЧитаетНастоящийПрофиль(unittest.TestCase):
    """Обещание из заголовка этого файла, проверенное кодом, а не словами.

    Десятки проверок задают подставной `HOME` и запускают пробу подпроцессом
    как `{**os.environ, "HOME": temp}`. Пока сборщик читал только домашний
    каталог, этого хватало. Теперь он уважает переменную профиля, как это
    делает хост, — и на машине, где она задана, она пережила бы подмену HOME
    и увела бы пробу в НАСТОЯЩИЙ профиль человека. Проверено измерением: две
    проверки краснели ровно от этого, при неизменном коде.

    Сторож стоит на входе в набор. Без этой проверки его можно снять, и
    заметит это не прогон, а тот, у кого переменная задана.
    """

    @staticmethod
    def _сторож():
        спец = importlib.util.spec_from_file_location("ss_conftest_проба", СТОРОЖ)
        модуль = importlib.util.module_from_spec(спец)
        спец.loader.exec_module(модуль)
        return модуль

    def test_указатель_на_профиль_снимается(self):
        сторож = self._сторож()
        было = os.environ.get(сторож.ПРОФИЛЬ)
        self.addCleanup(lambda: os.environ.__setitem__(сторож.ПРОФИЛЬ, было)
                        if было is not None
                        else os.environ.pop(сторож.ПРОФИЛЬ, None))
        os.environ[сторож.ПРОФИЛЬ] = "/каталог/чужого/профиля"
        сторож._отвязать_профиль()
        # `assertFalse`, а не `assertNotIn`: второе печатает КОНТЕЙНЕР, то есть
        # всё окружение человека вместе со значениями. Инструмент, который ищет
        # чужие утечки, не имеет права устраивать свою в отчёте о падении.
        self.assertFalse(сторож.ПРОФИЛЬ in os.environ,
                         "указатель на профиль пережил вход в набор — "
                         "подмена HOME больше ничего не гарантирует")

    def test_в_этом_прогоне_переменной_нет(self):
        """Мишень для проверки ниже. На машине, где переменная не задана, эта
        строка проходит вхолостую — потому и нужна вторая, со своим прогоном."""
        self.assertFalse(self._сторож().ПРОФИЛЬ in os.environ,
                         "указатель на профиль виден изнутри набора")

    def test_сторож_подключён_ко_входу_в_набор(self):
        """Существования сторожа мало: снявший ВЫЗОВ ничего бы не сломал.

        Проверка гоняет отдельный pytest с заданной переменной и одной
        мишенью — тем тестом выше. Отсюда переменная не видна: сторож уже
        отработал на входе в ЭТОТ прогон, и вхолостую проходило бы всё.
        """
        # Путь от корня репозитория: pytest собирает conftest.py от своего
        # корня вниз, и запуск из каталога с файлом отрезал бы `tests/conftest.py`
        # — проверялся бы прогон БЕЗ сторожа, то есть не тот случай.
        мишень = ("tests/external/" + Path(__file__).name +
                  "::НаборНеЧитаетНастоящийПрофиль"
                  "::test_в_этом_прогоне_переменной_нет")
        p = subprocess.run(
            [sys.executable, "-m", "pytest", мишень, "-q", "-p", "no:cacheprovider"],
            cwd=str(РЕПО), timeout=300,
            capture_output=True, text=True,
            env={**os.environ,
                 self._сторож().ПРОФИЛЬ: "/каталог/чужого/профиля",
                 "SUPERSTACK_IGNORE_PAUSE": "1"})
        self.assertEqual(p.returncode, 0,
                         "прогон с заданной переменной профиля не зелёный — "
                         "сторож не вызван на входе в набор:\n"
                         + (p.stdout or "")[-800:])


if __name__ == "__main__":
    unittest.main()
